create function pg_temp.assert_true(ok boolean,message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'ASSERTION: %',message; end if; end $$;
create function pg_temp.expect_denied(command text) returns void language plpgsql as $$ begin
 begin execute command; exception when insufficient_privilege or invalid_parameter_value or check_violation then return; end;
 raise exception 'Expected denial: %',command;
end $$;
insert into public.room_comments(room_id,author_id,body) values('33333333-3333-4333-8333-333333333333','22222222-2222-4222-8222-222222222222','친구의 새 글');
set role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',false);
select pg_temp.assert_true((public.get_my_library()->>'total')::integer=1004,'library exact total with 1000 drawings');
select pg_temp.assert_true(jsonb_array_length(public.get_my_library()->'rooms')=6,'bounded six-row page');
select pg_temp.assert_true(not(public.get_my_library()::text like '%strokes%') and not(public.get_my_library()::text like '%친구의 새 글%'),'metadata contains no drawings or message bodies');
select pg_temp.assert_true(exists(select 1 from jsonb_array_elements(public.get_my_library()->'rooms') r where r->>'id'='33333333-3333-4333-8333-333333333333' and (r->>'has_unread_comment')::boolean),'friend badge appears');
select pg_temp.expect_denied($q$select public.get_my_library(-1,'all',false)$q$);
select pg_temp.expect_denied($q$select public.get_my_library(0,'not-a-scope',false)$q$);
select public.set_room_hidden('33333333-3333-4333-8333-333333333333',true);
select public.set_room_hidden(id,true) from (select id from public.rooms where prompt like 'bulk-%' order by created_at desc limit 7) r;
select pg_temp.assert_true((public.get_my_library()->>'total')::integer=996 and jsonb_array_length(public.get_my_library()->'rooms')=6,'hidden items removed before limit/count');
select pg_temp.assert_true((public.get_my_library(0,'all',true)->>'total')::integer=8,'hidden view is paginated');
select pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(public.get_my_library(0)->'rooms') a join jsonb_array_elements(public.get_my_library(1)->'rooms') b on a->>'id'=b->>'id'),'pages do not overlap');
select pg_temp.assert_true((public.get_my_library(0,'host',false)->>'total')::integer=(select count(*) from public.rooms r where host_id=auth.uid() and not exists(select 1 from public.room_library_state s where s.room_id=r.id and s.hidden)),'host filter has server total');
select pg_temp.expect_denied($q$select public.set_room_hidden('99999999-9999-4999-8999-999999999990',true)$q$);
select pg_temp.expect_denied($q$update public.room_library_state set user_id='22222222-2222-4222-8222-222222222222'$q$);
select public.mark_room_comment_read('33333333-3333-4333-8333-333333333333',(select updated_at from public.room_comments where room_id='33333333-3333-4333-8333-333333333333'));
select pg_temp.assert_true((select hidden from public.room_library_state where room_id='33333333-3333-4333-8333-333333333333'),'marking read preserves hidden state');
select public.set_room_hidden('33333333-3333-4333-8333-333333333333',false);
select pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(public.get_my_library()->'rooms') r where r->>'id'='33333333-3333-4333-8333-333333333333' and (r->>'has_unread_comment')::boolean),'read badge clears and restore preserves read version');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',false);
select pg_temp.assert_true((public.get_my_library()->>'total')::integer=1004,'hiding does not affect friend library');
select pg_temp.assert_true((select count(*)=0 from public.room_library_state),'friend cannot read my preferences');
update public.room_comments set body=body where room_id='33333333-3333-4333-8333-333333333333';
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',false);
select pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(public.get_my_library()->'rooms') r where r->>'id'='33333333-3333-4333-8333-333333333333' and (r->>'has_unread_comment')::boolean),'identical retry does not create a new badge');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',false);
update public.room_comments set body='편집한 친구 글' where room_id='33333333-3333-4333-8333-333333333333';
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',false);
select public.mark_room_comment_read('33333333-3333-4333-8333-333333333333',(select comments_read_at from public.room_library_state where room_id='33333333-3333-4333-8333-333333333333'));
select pg_temp.assert_true(exists(select 1 from jsonb_array_elements(public.get_my_library()->'rooms') r where r->>'id'='33333333-3333-4333-8333-333333333333' and (r->>'has_unread_comment')::boolean),'late old read does not hide a newer edit');
select public.mark_room_comment_read('33333333-3333-4333-8333-333333333333','2100-01-01');
select pg_temp.assert_true((select s.comments_read_at=c.updated_at from public.room_library_state s join public.room_comments c using(room_id) where s.room_id='33333333-3333-4333-8333-333333333333'),'future read version clamps to latest message');
select pg_temp.assert_true(public.get_room_rematch('33333333-3333-4333-8333-333333333333')->>'starter_id'='22222222-2222-4222-8222-222222222222','old guest starts next round');
select public.request_room_rematch('33333333-3333-4333-8333-333333333333');
select public.request_room_rematch('33333333-3333-4333-8333-333333333333');
select pg_temp.assert_true((select count(*)=1 from public.room_rematches),'duplicate requests share a round');
select pg_temp.expect_denied($q$select public.request_room_rematch('55555555-5555-4555-8555-555555555555')$q$);
select pg_temp.expect_denied($q$select public.create_rematch_room('33333333-3333-4333-8333-333333333333','사칭','[{}]')$q$);
select pg_temp.expect_denied($q$insert into public.room_rematches(parent_room_id,requested_by) values('44444444-4444-4444-8444-444444444444',auth.uid())$q$);
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',false);
select pg_temp.expect_denied($q$select public.create_rematch_room('33333333-3333-4333-8333-333333333333','빈 그림','[]')$q$);
select public.create_rematch_room('33333333-3333-4333-8333-333333333333','울보 양파','[{"tool":"pen","color":"#000000","lineWidth":4,"points":[{"x":350,"y":100}]}]');
select public.create_rematch_room('33333333-3333-4333-8333-333333333333','재전송','[{}]');
select pg_temp.assert_true((select count(*)=1 from public.rooms where prompt='울보 양파' and host_id=auth.uid()),'idempotent creation never makes extra rounds');
select pg_temp.assert_true((select guest_id is null from public.rooms where id=(public.get_room_rematch('33333333-3333-4333-8333-333333333333')->>'next_room_id')::uuid),'partner joins only by explicit action');
reset role;
select pg_temp.assert_true((select count(*)=2 from public.drawings where room_id='33333333-3333-4333-8333-333333333333'),'original drawings preserved');
set role authenticated;
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999999',false);
select pg_temp.expect_denied($q$select public.get_room_rematch('33333333-3333-4333-8333-333333333333')$q$);
select pg_temp.expect_denied($q$select public.request_room_rematch('33333333-3333-4333-8333-333333333333')$q$);
reset role;
select set_config('test.next_code',(select r.code from public.rooms r join public.room_rematches m on m.next_room_id=r.id where m.parent_room_id='33333333-3333-4333-8333-333333333333'),false);
set role authenticated;
select pg_temp.expect_denied(format('select public.join_room(%L)',current_setting('test.next_code')));
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',false);
select * from public.join_room(current_setting('test.next_code'));
select pg_temp.assert_true((select r.host_id='22222222-2222-4222-8222-222222222222' and r.guest_id=auth.uid() and r.status='guest_joined' from public.rooms r where r.code=current_setting('test.next_code')),'same two people swap roles');
reset role;
update public.rooms set status='completed' where code=current_setting('test.next_code');
set role authenticated;
select public.request_room_rematch((public.get_room_rematch('33333333-3333-4333-8333-333333333333')->>'next_room_id')::uuid);
select pg_temp.assert_true(public.get_room_rematch((public.get_room_rematch('33333333-3333-4333-8333-333333333333')->>'next_room_id')::uuid)->>'starter_id'='11111111-1111-4111-8111-111111111111','roles can alternate again');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',false);
select public.create_rematch_room('44444444-4444-4444-8444-444444444444','만료 테스트','[{}]');
reset role;
select set_config('test.expired_id',(select next_room_id::text from public.room_rematches where parent_room_id='44444444-4444-4444-8444-444444444444'),false);
update public.rooms set expires_at=now()-interval '1 day' where id=current_setting('test.expired_id')::uuid;
set role authenticated;
select public.request_room_rematch('44444444-4444-4444-8444-444444444444');
select public.create_rematch_room('44444444-4444-4444-8444-444444444444','기한 후 새 판','[{}]');
select pg_temp.assert_true(public.get_room_rematch('44444444-4444-4444-8444-444444444444')->>'next_room_id'<>current_setting('test.expired_id'),'expired invitations can start a fresh round');
reset role;
set role anon;
select pg_temp.expect_denied($q$select public.get_my_library()$q$);
select pg_temp.expect_denied($q$select public.request_room_rematch('33333333-3333-4333-8333-333333333333')$q$);
select pg_temp.expect_denied($q$select * from public.room_library_state$q$);
reset role;
